"""Acting beats for Shino. Wrists are in metres from the upper chest in its
moving frame. Positive X always means the outside of that arm. The next two
vectors give finger direction and thumb edge; elbow guides live in the same frame.
"""
import bisect
import numpy as np

def hand(wrist, fingers, thumb=(0,.12,1), elbow=(.52,-.36,-.88), curl=.32, point=0):
    return np.array((*wrist,*fingers,*thumb,*elbow,curl,point),float)

