RESTING_HANDS = {**H, 'rest': H['hanging'], 'loose': H['hangingSoft']}

# Phase, left hand, right hand, torso pitch/yaw/roll, head pitch/yaw/roll,
# lateral weight shift and knee compression. Small offsets then travel through each beat.
def B(t,l,r,body=(0,0,0),head=(0,0,0),shift=0,dip=0):
    return (t,l,r,(*body,*head,shift,dip))
R=lambda t:B(t,'rest','loose',(1,-2,-1),(0,4,2),.010,.007)
def calm(t):
    return B(t,'hanging','hangingSoft',(1,-2,-1),(0,4,2),.010,.002)
