def sample_curve(times,values,t):
    """Cubic Hermite interpolation with monotone component tangents at each beat."""
    j=max(0,min(len(times)-2,bisect.bisect_right(times,t)-1));h=times[j+1]-times[j];u=np.clip((t-times[j])/h,0,1)
    a,b=values[j],values[j+1];d=(b-a)/h
    def tangent(neighbor):
        both=d*neighbor>0
        return np.divide(2*d*neighbor,d+neighbor,out=np.zeros_like(d),where=both)
    m=tangent((a-values[j-1])/(times[j]-times[j-1])) if j else 0
    n=tangent((values[j+2]-b)/(times[j+2]-times[j+1])) if j+2<len(times) else 0
    return (2*u**3-3*u*u+1)*a+(u**3-2*u*u+u)*h*m+(-2*u**3+3*u*u)*b+(u**3-u*u)*h*n

def channels(key, role):
    beats=SHEETS[key]
    hands=RESTING_HANDS if role != 'gait' else H
    return ([b[0] for b in beats],np.array([np.r_[hands[b[1]],hands[b[2]],b[3]] for b in beats]))
